MERGED = {}
for cid, ko, en, kw in ADD:                          # 같은 카드 id 가 여러 줄이면 합친다
    m = MERGED.setdefault(cid, ([], [], []))
    for lst, new in zip(m, (ko, en, kw)):
        lst.extend(x for x in new if x not in lst)
for f in [x for x in glob.glob("kb/cards/*.json") if not os.path.basename(x).startswith((".", "_"))]:
    d = json.load(open(f, encoding="utf8")); ch = False
    for c in d:
        if c["id"] in MERGED:
            ko, en, kw = MERGED[c["id"]]
            for v, k in ((ko, "ko"), (en, "en")):
                for x in v:
                    if x not in c["q"][k]:
                        c["q"][k].append(x); ch = True
            for x in kw:
                if x not in c.setdefault("kw", []):
                    c["kw"].append(x); ch = True
    if ch:
        json.dump(d, open(f, "w", encoding="utf8"), ensure_ascii=False, indent=1)
